"""Generate tools/analysis/testdata/p0_3_t1_signals.json (P0.3-T1 signal definitions).

Run once; the output is committed so the C++ and Python tests read identical definitions. Phases of
Case B come from numpy's PCG64 generator with the seed below, written with 17 significant digits.
"""

from __future__ import annotations

import json
import math
from pathlib import Path

import numpy as np

SEED = 20261011


def partial(f: float, a: float, sigma: float, phase: float) -> dict[str, float]:
    return {"frequency_hz": f, "amplitude": a, "sigma_per_s": sigma, "phase_rad": phase}


def build() -> dict[str, object]:
    rng = np.random.default_rng(SEED)
    sigma_t60_20 = 3.0 * math.log(10.0) / 20.0
    cases: list[dict[str, object]] = []

    for f, phase in ((27.5, 0.7), (261.6, -1.3), (4186.0, 2.1)):
        cases.append(
            {
                "name": f"A_{f:g}Hz",
                "case": "A",
                "oracle": "ORC-01 setup",
                "sample_rates_hz": [48000],
                "duration_s": 4.0,
                "partials": [partial(f, 1.0, sigma_t60_20, phase)],
            }
        )

    f0, b = 55.0, 4.0e-4
    phases = rng.uniform(0.0, 2.0 * math.pi, 30)
    parts = []
    numbers = []
    for n in range(1, 31):
        fn = n * f0 * math.sqrt(1.0 + b * n * n)
        parts.append(partial(fn, 1.0 / n, 0.3 + 1e-6 * fn * fn, float(phases[n - 1])))
        numbers.append(n)
    cases.append(
        {
            "name": "B_stiff_string",
            "case": "B",
            "sample_rates_hz": [44100, 48000, 96000],
            "duration_s": 4.0,
            "f0_hz": f0,
            "inharmonicity_b": b,
            "partial_numbers": numbers,
            "partials": parts,
        }
    )

    cases.append(
        {
            "name": "C_unison",
            "case": "C",
            "oracle": "ORC-07 setup",
            "sample_rates_hz": [48000],
            "duration_s": 4.0,
            "partials": [partial(261.6, 1.0, 0.5, 0.4), partial(262.6, 1.0, 1.5, -2.2)],
        }
    )
    return {
        "description": (
            "P0.3-T1 signal definitions: x(t) = sum a exp(-sigma t) cos(2 pi f t + phase), "
            "t = n / sample_rate, n = 0 .. round(duration * sample_rate) - 1. Generated by "
            "make_p0_3_t1_signals.py."
        ),
        "version": 1,
        "cases": cases,
    }


if __name__ == "__main__":
    out = Path(__file__).with_name("p0_3_t1_signals.json")
    out.write_text(json.dumps(build(), indent=2) + "\n", encoding="utf-8")
